"""Prospective v133 plan; no engine, no outcomes, no parameter selection."""
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'tools/auto_tuning'))
from common import atomic_json,file_hash,read_json,utc_now
DOC=ROOT/'docs/validation/auto_tuning/benchmark_v133'

def main():
    assert not (DOC/'run_plan.json').exists()
    catalog=read_json(ROOT/'features/evaluator_virtual_cursor/resources/benchmark_eval_v133.json')
    cells=[]
    for hz in [120,60]:
        for d in catalog['scenarios']:
            cells.append({'scenario':d['id'],'hz':hz,'mode':'headless','repeat':0,'lane':'ADAPTIVE_CAPTURE_SOURCE','purpose':'bounded_preparation_capture_not_fixed_repeat'})
            for mode in ['headless','rendered_scripted']:cells.append({'scenario':d['id'],'hz':hz,'mode':mode,'repeat':1,'lane':'FIXED_VIRTUAL_REPLAY','purpose':'first_matched_pair_if_actual_onset_valid'})
            if d['id'] in ['foot_supported_step','two_hand_release_stop']:cells.append({'scenario':d['id'],'hz':hz,'mode':'headless','repeat':9,'lane':'FIXED_VIRTUAL_REPLAY','purpose':'new_projection_probe_OFF_control_if_onset_valid'})
        for d in catalog['scenarios'][:4]:
            for repeat in [2,3]:
                for mode in ['headless','rendered_scripted']:cells.append({'scenario':d['id'],'hz':hz,'mode':mode,'repeat':repeat,'lane':'FIXED_VIRTUAL_REPLAY','purpose':'independent_process_replication_if_prior_gates_valid'})
    assert len(cells)==72
    tapes={str(h):{'path':str(ROOT/f'builds/eval_virtual_cursor/requal_20261020_r1/capture/tapes/catch_{h}.json'),'sha256':file_hash(ROOT/f'builds/eval_virtual_cursor/requal_20261020_r1/capture/tapes/catch_{h}.json')} for h in [120,60]}
    plan={'id':'benchmark_v133_r1','frozen_before_qualification_utc':utc_now(),'canonical_backing':[1024,576],'logical_viewport':[1920,1080],'seed':101,'source_catalog_sha256':file_hash(ROOT/'features/evaluator_virtual_cursor/resources/benchmark_eval_v133.json'),'reference_tapes':tapes,'reference_cells':[{'scenario':'swing_catch_train','hz':hz,'mode':mode,'repeat':r} for hz in [120,60] for r in [1,2,3] for mode in ['headless','rendered_scripted']],'new_domain_cells':cells,'max_new_domain_attempts_including_captures':72,'max_reference_attempts':12,'max_negative_attempts':8,'max_post_hard_stop_diagnostics':4,'max_qualification_attempts':96,'regressions_separate':'Explicit user confirmation: sim, regressões à parte; 34 original suites plus ordinary startup/MCP/release safety are separate validation, never new-domain passes.','pure_preflights':{'positive':12,'negative_wrong_size':1,'gameplay_bodies_created':0,'not_physical_outcomes':True},'capture_accounting':'4 primary domains ×2Hz ×(1 adaptive capture +6 FIXED replays)=56; foot/stop ×2Hz ×(1 capture +2 fixed replays +1 probeOFF control)=16. Adaptive captures never count as fixed-repeat evidence.','foot_stop_policy':'n1 fixed pair per Hz is DIAGNOSTIC_ONLY even if task succeeds; explicit ranking exclusion with consequences. No automatic conversion of unused budget to more coverage.','order':'BQ1 pure preflight; BQ2 six catch pairs; BQ5a120Hz capture and firstpairs; BQ5b120Hz primary repetitions; BQ5c60Hz same sequence; negatives only named prospective cases; final decision.','hard_stops':['invalid_tape_or_source','canonical_environment_clock_or_owner','unexpected_requested_accepted_applied_input_mismatch','missing_required_trace','strict_first_divergence_any_required_channel','hard_physical_invariant','invalid_metric_or_runtime_recompute'],'domain_precondition_failure':'valid simulation with no legal onset -> PRECONDITION_NOT_MET/DIAGNOSTIC_ONLY; skip its fixed replay cells; not a safety pass or zero progress.','measurement_task_failure':'task_succeeded false/latency censored/interruption keeps domain diagnostic; no physical/scoring rescue.','new_domain_eligibility':'Only four primary domains with n3 FIXED modepairs at BOTHHz; all required channels exact; actual onset and signed positive progress >1e-6m, usefulvelocity>.02m/s sustained.05s, legal support and complete authorized horizon; metrics remain separated objectives; no score/search.','thresholds':{'quiet_directed_speed_m_s':.1,'quiet_full_spin_rad_s':.2,'quiet_elapsed_dwell_s':.25,'quiet_max_wait_s':5,'stop_directed_speed_band_m_s':[.15,.5],'stop_drive_max_s':2,'latency_positive_velocity_m_s':.02,'latency_dwell_s':.05,'path_numerical_floor_m':1e-6,'settle_full_speed_m_s':.1,'settle_full_spin_rad_s':.2,'settle_dwell_s':.25},'canonical_compare':'Match same physicalHz/backing, same engine/source/policy/tape; full required channels including feet/nativeground/restlengths/reactions/planner/bodycontacts. Runtime IDs mapped to real stable support instance chains, not compared across processes.','numeric_policy':'No contact/physics envelope. Typed Vector2 is native float32 as observed in pinned build; raw JSON scalar parser and actual API argument recorded. Precise JSON records and binary64 ray sidecars retained.','portability_1440':'NOT_RUN_RESERVED_NO_BUDGET_REALLOCATION','generalization_seeds_hardware_rays':'GENERALIZATION_NOT_TESTED; seed101 repeats only','hardware_interference':'Actual delivered external events recorded if present. Old physical mouse/focus evidence preserved separately; pure ownership controls are not human/physical OS tests.','private_holdout_outcomes_accessed':False,'optimizer':'OFF','human_playtests':0}
    atomic_json(DOC/'run_plan.json',plan)
    (DOC/'environment_contract.md').write_text('''# Canonical environment contract v133

Qualification uses actual1024×576 backing and logical1920×1080. CLI is --resolution1024x576; it is observed before gameplay-body construction. Clock settles on two consecutive actual1/Hz callbacks with no lab. A failed setup is rejected, never numerically repaired after execution. Requested and actual screen/window position/mode, display server, stretch/canvas/global/final, camera owner/FOV/near/keep-aspect and engine/backend identities are preserved. Unavailable headless DPI/screen scaling is typed unavailable, not zero or asserted equal to Windows.

Twelve pure preflights create zero gameplay bodies; they verify environment/clock/API only, not V0 gameplay. Every BQ2 process separately proves its preworld setup and actual ACTIVE V0 owner, profile4/A0/B1, real pick chain and cleanup. Normal profile2/LIVE is a separate regression. The capture lane adaptively prepares contacts through ordinary inputs; the fixed lane only consumes frozen frame tapes. Capture is not counted as fixed replay.

The old two tapes and source hashes remain unchanged. Their compatibility with v133 is explicit via capture and runtime source maps and reviewed read-only source delta. No parameter Resource is duplicated or overridden; original baseline identity is verified before its first step. One worker; one gameplay Lab per process; synchronous retirement/cleanup.

During an episode provider checks ownership/viewport/FOV/bindings/clock; the v133 driver also checks observed window mode/position/screen and canvas/final transforms every PRE. Resize callbacks invalidate. Camera transforms may evolve physically and are measured, not frozen. Real hardware/focus rejection events are kept; execution gaps invalidate instead of inserting synthetic ticks. No new LIVE input or camera behavior is introduced.

Native contact reporting may be incomplete; its configured limit is recorded. A zero-size contact buffer does not prove no collision. New climbing-only domains additionally use the existing read-only swept-ground query observer; potential ground intersections or native walking authority interrupt their measurement. Catch retains its honestly labelled historical B1/native-ground contribution.
''',encoding='utf-8')
    print('Prospective plan written:72 new-domain attempts +12 reference +8 negative +4 issue diagnostics =96; regressions separate by user instruction')
if __name__=='__main__':main()
